"""Writes docs/uml/er.puml from the SQLAlchemy models, so the ER diagram always matches the schema.

Run from backend/:  python ../docs/uml/gen_er.py
"""

from pathlib import Path

import app.models  # noqa: F401  (imports every model)
from app.core.database import Base

OUT = Path(__file__).with_name("er.puml")

lines = [
    "@startuml er",
    "' Generated by docs/uml/gen_er.py from backend/app/models - do not edit by hand.",
    "hide circle",
    "skinparam linetype ortho",
    "skinparam shadowing false",
    "skinparam defaultFontName Arial",
    "skinparam EntityBackgroundColor #FFFFFF",
    "skinparam EntityBorderColor #333333",
    "left to right direction",
]
for table in sorted(Base.metadata.tables.values(), key=lambda t: t.name):
    lines.append(f"entity {table.name} {{")
    for col in table.columns:
        fk = next(iter(col.foreign_keys), None)
        tag = "<<PK>> " if col.primary_key else ("<<FK>> " if fk else "")
        null = "" if col.nullable or col.primary_key else " NOT NULL"
        lines.append(f"  {'*' if col.primary_key else ''}{col.name} : {col.type}{null} {tag}".rstrip())
        if col.primary_key and not fk:
            pass
    lines.append("}")
for table in sorted(Base.metadata.tables.values(), key=lambda t: t.name):
    seen = set()
    for fk in table.foreign_keys:
        parent = fk.column.table.name
        if (parent, fk.parent.name) in seen:
            continue
        seen.add((parent, fk.parent.name))
        many = "o{" if not fk.parent.unique else "o|"
        lines.append(f"{parent} ||--{many} {table.name} : {fk.parent.name}")
lines.append("@enduml")
OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"wrote {OUT} ({len(Base.metadata.tables)} tables)")
